async function compileFlowEntries(){
  await mkdir(temporary,{recursive:true});
  await writeFile(path.join(temporary,'package.json'),'{"type":"module"}\n');
  const selected=['flow-layout','flow','diagram-viewer'];
  for(const name of selected){
    const sourcePath=path.join(site,'src/lib',name+'.ts');let source=await readFile(sourcePath,'utf8');
    const pattern=/import\s+(\w+)\s+from\s+['"]([^'"]+\.json)['"](?:\s+with\s*\{[^}]+\})?\s*;/g;
    for(const match of [...source.matchAll(pattern)]){const value=JSON.parse(await readFile(path.resolve(path.dirname(sourcePath),match[2]),'utf8'));source=source.replace(match[0],`const ${match[1]} = ${JSON.stringify(value)};`);}
    for(const match of source.matchAll(/from\s+['"]\.\/([^'"]+)['"]/g))assert(selected.includes(match[1].replace(/\.ts$/,'')),'only selected flow dependencies');
    source=compiler.transpileModule(source,{compilerOptions:{target:compiler.ScriptTarget.ES2022,module:compiler.ModuleKind.ESNext},fileName:sourcePath}).outputText;
    source=source.replace(/(from\s+['"])(\.\/?[^'"]+)(['"])/g,(_,prefix,specifier,suffix)=>`${prefix}${specifier.replace(/\.ts$/,'').replace(/(?<!\.js)$/,'.js')}${suffix}`);
    source=source.replace(/import\.meta\.env/g,'({ BASE_URL: "/flowchartcp/" })');
    await writeFile(path.join(temporary,name+'.js'),source);
  }
}
