// A read-only mirror: source article files are symlinks, but mutations replace
// the mirror link itself before writing. No source file is opened for writing.
async function mirrorDirectory(source,destination){await mkdir(destination,{recursive:true});for(const entry of await readdir(source,{withFileTypes:true})){
  if(entry.name.startsWith('.'))continue;const from=path.join(source,entry.name),to=path.join(destination,entry.name);
  if(entry.isDirectory())await mirrorDirectory(from,to);else await symlink(from,to);}}
test('an invalid actual article C++ fence fails the real content preflight and removes production coverage',async()=>{
  const {flow}=await implementation;const[plan,techniques,references,walks]=await Promise.all([json('data/coverage-plan.json'),collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json('data/problem-walks.json')]);
  const mirror=await mkdtemp(path.join(tmpdir(),'flowchartcp-ioi2017-books-preflight-'));const originals=[];
  try{await mirrorDirectory(path.join(site,'data'),path.join(mirror,'data'));await mirrorDirectory(path.join(site,'src/content/docs'),path.join(mirror,'src/content/docs'));
    for(const directory of ['public','research','vendor'])await symlink(path.join(site,directory),path.join(mirror,directory),'dir');
    const clean=await validateSite(mirror);assert.deepEqual(clean.errors,[],'unmodified isolated mirror must pass the actual preflight');
    for(const current of cases){const relative='src/content/docs/techniques/'+current.id+'.mdx',target=path.join(mirror,relative),source=await readFile(path.join(site,relative),'utf8');
      originals.push([relative,bytesHash(source)]);const broken=source.replace(/^```cpp\s*\n[\s\S]*?^```\s*$/m,'```cpp\n```');assert.notEqual(broken,source);
      await unlink(target);await writeFile(target,broken);const invalid=await validateSite(mirror);
      assert(invalid.errors.some(error=>error.includes(current.id)&&/再利用可能な実装例/.test(error)),'actual invalid fence rejected by product preflight');
      const audit=await json(current.audit),data=coverageData(flow,techniques,references,walks,invalid.errors.length===0);assessed(audit,data,selection(plan,current),assessCorpus(audit,coverageData(flow,techniques,references,walks),selection(plan,current)).reviewedProblems,0);
      await unlink(target);await symlink(path.join(site,relative),target);
    }
  }finally{await rm(mirror,{recursive:true,force:true});}
  for(const[relative,hash]of originals)assert.equal(bytesHash(await readFile(path.join(site,relative))),hash,'source MDX bytes remain unchanged');
});
